// Validate payload structure and security header
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

// Check event type
if (body.event_type !== 'CUSTOMER_LOGIN') {
  throw new Error(`Unsupported event type: ${body.event_type}. Only CUSTOMER_LOGIN is handled.`);
}

if (!body.email || !body.customer_id) {
  throw new Error('Malformed event: Missing required email or customer_id.');
}

return [{
  json: {
    valid: true,
    event_id: body.event_id,
    customer_id: body.customer_id,
    email: body.email,
    first_name: body.first_name || 'Valued Collector',
    timestamp: body.timestamp || new Date().toISOString(),
    provider: body.provider || 'N8N'
  }
}];
